// Hierarchical Beta-Binomial model
// y_i ~ Binomial(n_i, theta_i)
// theta_i ~ Beta(alpha, beta)
// Prior: p(alpha, beta) proportional to (alpha + beta)^(-5/2)

data {
  int<lower=1> N;            // number of observations
  array[N] int<lower=0> y;   // successes
  array[N] int<lower=0> n;   // trials
}

parameters {
  real<lower=0> alpha;                  // Beta shape parameter 1
  real<lower=0> beta;                   // Beta shape parameter 2
  vector<lower=0, upper=1>[N] theta;    // per-observation probabilities
}

model {
  // Hyperprior: p(alpha, beta) proportional to (alpha + beta)^(-5/2)
  // log p = -(5/2) * log(alpha + beta) + const
  target += -2.5 * log(alpha + beta);

  // Hierarchical prior: theta_i ~ Beta(alpha, beta)
  theta ~ beta(alpha, beta);

  // Likelihood: y_i ~ Binomial(n_i, theta_i)
  y ~ binomial(n, theta);
}
